def route_order(legs):
    nxt = {stop: after for stop, after in legs}
    pointed = {after for _, after in legs if after is not None}
    stop = next((s for s in nxt if s not in pointed), None)
    route = []
    while stop is not None:
        route.append(stop)
        stop = nxt[stop]
    return route

