def route_order(legs):
    pointed = {after for _, after in legs if after is not None}
    stop = next((s for s, _ in legs if s not in pointed), None)
    route = []
    while stop is not None:
        route.append(stop)
        nxt = None
        for s, after in legs:
            if s == stop:
                nxt = after
                break
        stop = nxt
    return route
